func f<s/T>(value: s/T, x: T) -> ()
    s is owner or uniq
    T is Copy
    var v = value@move
    let h = func [v] () -> ()
        _ = v@follow
    var pair = (h@move, 1)
    v@follow = x
    pair.0()
public func main() -> ()
    var n: i32 = 1
    f(n, 9)
    Console.writeLine("n=\(n)")

