func keep<F>(f: F) -> F => f@move
func f<s/T>(value: s/T) -> ()
    s is owner or uniq
    T is Copy
    let kept = keep(value)
    _ = kept@follow
public func main() -> ()
    var n: i32 = 1
    f(n)
    Console.writeLine("n=\(n)")

